import * as THREE from 'three/webgpu';
import { 
  uniform, texture, uv, 
  positionLocal, normalLocal, 
  positionWorld, normalWorld, cameraPosition,
  vec2, vec3, float, mix, dot
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Load cached textures
  const colorMap = ctx.textureLoader(config.assets.imageUrl);
  const depthMap = ctx.textureLoader(config.assets.depthMapUrl);

  colorMap.colorSpace = THREE.SRGBColorSpace;

  // Atlas region
  const region = config.atlasRegion || { x: 0, y: 0, w: 512, h: 512 };
  const atlasW = 512;
  const atlasH = 320;

  const u0 = region.x / atlasW;
  const v0 = 1 - (region.y + region.h) / atlasH;
  const u1 = (region.x + region.w) / atlasW;
  const v1 = 1 - region.y / atlasH;

  // Tessellated plane geometry (64x64 segments)
  const planeW = 2.5;
  const planeH = 0.4;
  const geometry = new THREE.PlaneGeometry(planeW, planeH, 64, 64);

  // Displacement strength uniform
  const displaceStrength = uniform(0.05);

  // Machined-metal PBR material with clearcoat
  const material = new THREE.MeshPhysicalNodeMaterial();
  material.metalness = 0.5;
  material.roughness = 0.55;
  material.clearcoat = 0.22;
  material.clearcoatRoughness = 0.45;

  // Remapped UV for atlas sampling
  const atlasUV = vec2(
    mix(float(u0), float(u1), uv().x),
    mix(float(v0), float(v1), uv().y)
  );

  // Depth sample for displacement
  const depthSample = texture(depthMap, atlasUV).r;

  // Vertex displacement along local normal (Z for plane)
  material.positionNode = positionLocal.add(
    normalLocal.mul(depthSample.mul(displaceStrength))
  );

  // Surface color from texture
  material.colorNode = texture(colorMap, atlasUV);

  // Accent rim light (#ff2a38)
  const viewDir = positionWorld.sub(cameraPosition).normalize();
  const rimFactor = float(1).sub(normalWorld.dot(viewDir.negate())).pow(float(2));
  const accentColor = vec3(float(1.0), float(0.165), float(0.220));
  material.emissiveNode = rimFactor.mul(accentColor).mul(float(0.12));

  // Build mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.position[0], config.position[1], config.position[2]);
  mesh.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
  mesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);

  // Apply cinematic primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives && ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](mesh, primitive.params);
      }
    });
  }

  // Store data bindings
  mesh.userData.bindings = config.dataBindings || [];

  // Preserve any handlers set by primitives
  mesh.userData.handlers = mesh.userData.handlers || {};
  const existingHover = mesh.userData.handlers.hover;
  const existingHoverEnd = mesh.userData.handlers.hoverEnd;

  // Hover: rise-in subtle (0.15 scene units)
  const baseY = config.position[1];
  let hoverTl = null;

  mesh.userData.handlers.hover = (event) => {
    if (existingHover) existingHover(event);
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(mesh.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power3.out'
    });
  };

  mesh.userData.handlers.hoverEnd = (event) => {
    if (existingHoverEnd) existingHoverEnd(event);
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(mesh.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power3.out'
    });
  };

  // Click: emit hub-pricing.select
  mesh.userData.handlers.click = () => {
    if (ctx.emit) {
      ctx.emit('hub-pricing.select', { nodeId: config.id, source: 'list-row' });
    }
  };

  // Entrance: weighted-settle (overshoot 1.04 -> 1.0, power4.out, 0.9s)
  const entranceTl = gsap.timeline();
  entranceTl.set(mesh.position, { y: baseY + 0.4 });
  entranceTl.set(mesh.scale, { x: 1.04, y: 1.04, z: 1.04 });
  entranceTl.to(mesh.position, {
    y: baseY,
    duration: 0.9,
    ease: 'power4.out'
  });
  entranceTl.to(mesh.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, '<');

  // Cleanup
  mesh.userData.cleanup = () => {
    if (entranceTl) entranceTl.kill();
    if (hoverTl) hoverTl.kill();
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
